  str_n7_mission_desc_2 = "คุณมุ่งหน้าไปยังอัมบราตัน เมืองที่ปกคลุมด้วยเงามืด หลังจากได้รับจดหมาย",
  str_n7_mission_desc_3 = "หลังจากพบกับเบเธล คุณก็มาถึงสำนักงานใหญ่ของกิลด์เพื่อเตรียมการรับมอบทรัพย์สินเคเลสไทต์",
  str_n7_mission_desc_4 = "สำนักงานใหญ่โดนอิคลิพไซท์โจมตีเหรอ? นี่มันเกิดอะไรขึ้น...?",
  str_n7_mission_desc_5 = "เมื่อเผชิญกับสถานการณ์ที่ยากจะตัดสินใจ ลุคจึงเสนอให้คุณไปลองเสี่ยงโชคดูที่บาร์สี่แยก",
  str_n7_mission_desc_6 = "การสืบสวนยังคงหยุดนิ่ง คุณตัดสินใจไปที่การประมูลใต้ดินก่อนโดยไปกับลุค",
  str_n7_mission_desc_7 = "ไรน์ทรยศเจ้าแห่งเงาเหรอ? คุณต้องตามหาเบเธลและบอกเธอทันที!",
  str_n7_mission_desc_8 = "เบเธลก็โดนโจมตีด้วย ตามที่คุณก็นึกกลัว ดูเหมือนว่ากำลังเกิดกบฏขึ้นในอัมบราตัน...",
  str_n7_mission_desc_9 = "เมื่อได้ยินว่ากิลด์ใหญ่ ๆ ก็พากันถูกโจมตีด้วยเช่นกัน คุณจึงตัดสินใจให้การสนับสนุนทันที",
  str_n7_mission_desc_10 = "หลังจากได้รับคำแนะนำเพิ่มเติม คุณก็มาถึงที่สำนักงานใหญ่ของแก๊งเพลิงเหล็กกล้า ดูเหมือนว่ากลุ่มหัวหน้ากิลด์ใหญ่ ๆ จะถูกจับตัวไว้ที่นี่...",
  str_n7_mission_desc_11 = "ตอนนี้ไรน์กับม้อดคงกำลังโจมตีเขื่อนอยู่ รีบไปที่เขื่อนแห่งรอยแผลทันที!",
  str_n7_mission_desc_long_1 = "คุณได้รับจดหมายจากอัมบราตันเพื่อเชิญให้ไปรับมอบทรัพย์สินที่ชาวเคเลสไทต์ทิ้งเอาไว้\nนาโรเซลก็ได้ยินมาเช่นกันว่ามีของชิ้นพิเศษที่รู้จักกันว่าเป็นส่วนประกอบของห้องซิมูเลชั่นอยู่ในการประมูลใต้ดินที่อัมบราตัน...",
  str_n7_mission_desc_long_2 = "นี่คือ \"เมืองที่ปกคลุมด้วยเงามืด\"\nคุณได้พบกับเบเธล หัวหน้ากิลด์ แต่อิคลิพไซท์โจมตีคุณโดยไม่ทันตั้งตัวบนเส้นทางสู่อัมบราตัน\nโชคดีที่ลุค ผู้บัญชาการหน่วยทหารรับจ้างในพื้นที่ โผล่มาได้ทันเวลาพอดีและตัดสินใจร่วมเดินทางไปกับคุณด้วย",
  str_n7_mission_desc_long_3 = "เมื่อคุณไปถึงกิลด์และเตรียมพร้อมสำหรับกระบวนการรับมอบ ก็เกิดเหตุอิคลิพไซท์โจมตีขึ้นอีกครั้งหนึ่ง\nเมื่อคิดดูว่านี่เป็นพื้นที่ที่มีการคุ้มกันอย่างแน่นหนา ก็ทำให้สงสัยว่านี่เป็นเหตุบังเอิญจริงหรือ?",
  str_n7_mission_desc_long_4 = "ประจวบเหมาะเหลือเกินที่พิตต์แมนก็มาที่อัมบราตันเพื่อสอบสวนเรื่องยาเสริมพลังลึกลับด้วยเช่นกัน ดังนั้นคุณจึงได้พันธมิตรเพิ่มอีกหนึ่งคน\nลุคหวังว่าจะได้เบาะแสเพิ่ม จึงตัดสินใจพาคุณไปยังที่แห่งหนึ่ง...",
  str_n7_mission_desc_long_5 = "คุณได้เผชิญหน้ากับไรน์จากกิลด์สิงโตน้ำเงินที่บาร์สี่แยก พร้อมด้วยบุคคลลึกลับอีกคนหนึ่ง\nทั้งสองขัดขวางภารกิจของคุณได้สำเร็จ และแทนที่จะพบเบาะแสที่มีประโยชน์ คุณกลับพบว่าตัวเองถูกโจมตีอีกครั้งหนึ่ง\nนอกจากนี้ยังดูเหมือนว่าเบเธลได้จากไปแบบรีบร้อนสุด ๆ อีกด้วย...",
  str_n7_mission_desc_long_6 = "เนื่องจากไม่สามารถดำเนินการสืบสวนต่อไปได้ คุณกับลุคจึงไปที่โรงประมูลเพื่อตามหาส่วนประกอบของห้องซิมูเลชั่น แต่กลับต้องเจอไรน์กับพรรคพวกอีกครั้งหนึ่ง\nคราวนี้พวกมันเข้ายึดพื้นที่ได้อย่างรวดเร็วและไร้ความปรานี และประกาศว่าบัดนี้อีสต์วานตายแล้ว",
  str_n7_mission_desc_long_7 = "หลังออกจากการประมูล คุณก็รีบไปที่กิลด์เพื่อตามหาเบเธล\nคุณพบเบเธลที่สำนักงานใหญ่และเผชิญกับการลอบสังหาร โชคดีที่ทุกอย่างดูจะอยู่ในความควบคุมแล้วในเวลานี้",
  str_n7_mission_desc_long_8 = "เรื่องที่คุณกลัวที่สุดกลายเป็นความจริงขึ้นมา... ไรน์ก่อกบฏจริง ๆ และคนของเบเธลก็อยู่ในกลุ่มผู้ทรยศด้วย\nส่วนเจ้าแห่งเงานั้นไม่มีผู้ใดเชื่อว่าตายไปแล้วจริง ๆ\nเรื่องเร่งด่วนที่สุดของคุณคือต้องช่วยเหลือกิลด์ต่าง ๆ ที่ถูกโจมตีและระงับความวุ่นวายนี้ให้ได้...",
  str_n7_mission_desc_long_9 = "เมื่อไปถึงกิลด์หลินที่ถูกโจมตี ดูเหมือนว่าจะมีคนช่วยจัดการกับสภาวะความลำบากไปเรียบร้อยแล้ว\nนอกจากนี้ลุคยังได้รับรู้เบาะแสใหม่ที่นำคุณไปยังจุดหมายต่อไป นั่นคือ สำนักงานใหญ่แก๊งเพลิงเหล็กกล้า",
  str_n7_mission_desc_long_10 = "คุณมาถึงสำนักงานใหญ่แก๊งเพลิงเหล็กกล้า และช่วยชีวิตกลุ่มหัวหน้ากิลด์ที่ถูกลักพาตัวไปจากการประมูล\nในที่สุดแก๊งอีสต์วานก็ปรากฏตัวโดยไม่คาดคิดและเข้าดำเนินการรักษาความสงบเรียบร้อย\nก้าวต่อไปของคุณตอนนี้คือต้องตามจับตัวคนทรยศเบื้องหลังเรื่องทั้งหมดนี้ที่เขื่อนแห่งรอยแผล!",
  str_n7_mission_desc_long_11 = "แผนการของเขาล้มเหลว ม้อดผู้โกรธจัดจึงกลืนกินยาเสริมพลังเข้าไป\nภายใต้การสั่งการของเจ้าแห่งเงา คุณได้รับชัยชนะและความจริงก็เปิดเผยออกมาในที่สุด",
  str_n7_mission_desc_long_12 = "คำถามมากมายในเรื่องนี้ยังคงอยู่... นอกจากนี้พิตต์แมนยังตัดสินใจที่จะทำการสืบสวนของเขาต่อไปอีกด้วย\nคุณได้รับส่วนประกอบของห้องซิมูเลชั่นที่ตามหาอยู่ ซึ่งอาจมีประโยชน์อย่างมากในอนาคต...",
  str_n7_paper_1_1_title = "<size=70><color=#353330>สิงโตน้ำเงินคำราม!\nประกาศรางวัลอารีน่าใต้ดินสองเท่า!</color></size>",
  str_n7_paper_1_2_title = "สัมภาษณ์เจ้าแห่งเงา",
  str_n7_paper_1_3_title = "<size=32><color=#353330>สารานุกรมอิคลิพไซท์ #50\nเคเลสไทต์คนสุดท้าย</color></size>",
  str_n7_paper_1_4_title = "<size=35><color=#353330>มหกรรมลดราคางานจิปาถะฤดูฝน</color></size>",
  str_n7_paper_1_5_title = "<size=35><color=#353330>มิลเลอร์ที่สามเชิดเงินหนี!\nร้านเกียรติยศลดราคาพิเศษ!</color></size>",
  str_n7_paper_2_1_title = "<size=70><color=#353330>พายุกำลังมา!\nจงเจิดจ้า ดาวแห่งอารีน่าใต้ดิน!</color></size>",
  str_n7_paper_2_2_title = "มิสตี้ซาลอน\nงานฉลองไฮโซ",
  str_n7_paper_2_3_title = "<size=45><color=#353330>แมวหลงทาง</color></size>",
  str_n7_paper_2_4_title = "<size=35><color=#353330>บริการตกแต่งภายในโดยสหภาพผู้ส่งสาร!</color></size>",
  str_n7_paper_2_5_title = "<size=35><color=#353330>กิลด์หลินปิดชั่วคราว</color></size>",
  str_n7_paper_3_1_title = "<size=60><color=#353330>เคเลสไทต์พลิกล็อกคว้าชัยในอารีน่าใต้ดิน!\nร้านค้าอายุหนึ่งศตวรรษรอดแล้วเหรอ?</color></size>",
  str_n7_paper_3_2_title = "ฟรีหมายถึงกำไรเหรอ?\nสัมภาษณ์คุณเชโอล!",
  str_n7_paper_3_3_title = "<size=35><color=#353330>พบอิคลิพไซท์ประหลาด\nเราเชื่อในเซนต์จอห์น</color></size>",
  str_n7_paper_3_4_title = "<size=35><color=#353330>ความสงบในอัมบราตันงั้นหรือ?\nลือกระฉ่อน ยักษ์ใหญ่ในอุตสาหกรรมจะยุติข้อพิพาท</color></size>",
  str_n7_paper_3_5_title = "<size=35><color=#353330>แก๊งเม้าท์มอย</color></size>",
  str_n7_paper_4_1_title = "<size=60><color=#353330>ข่าวด่วน: สิงโตน้ำเงินเขี้ยวเปล่า!\nไรน์เป็นผู้ต้องสงสัยเหตุโจมตีเขื่อน!</color></size>",
  str_n7_paper_4_2_title = "ม้ามืด\nมาเหนือคว้าชัยชนะ",
  str_n7_paper_4_3_title = "<size=35><color=#353330>สเปียร์โรว์คว้ารางวัลความปลอดภัยสาธารณะอีกครั้ง</color></size>",
  str_n7_paper_4_4_title = "<size=35><color=#353330>ชนชั้นสูงเปิดการประมูลใต้ดินผิดกฎหมาย\nมีฉากหน้าเป็น \"ซาลอน\" มานานหลายปี</color></size>",
  str_n7_paper_4_5_title = "<size=35><color=#353330>ซากศพอิคลิพไซท์ถูกทิ้งเกลื่อน\nศาลยุติธรรมอาจมีเอี่ยว</color></size>",
  str_n7_paper_5_1_title = "<size=70><color=#353330>เคเลสไทต์ผู้กล้าจงเจริญ\nมิตรภาพจงเจริญ!</color></size>",
  str_n7_paper_5_2_title = "สำนักงานใหญ่กิลด์ยื่นมือเข้าช่วย\nการประมูลใต้ดินจะกลับมา",
  str_n7_paper_5_3_title = "<size=31><color=#353330>อัญเชิญทหารรับจ้างอัคคีขาว</color></size>",
  str_n7_paper_5_4_title = "<size=35><color=#353330>ข่าวด่วน! ระบุตัวแฟนท่อมตามถนนในอัมบราตันได้แล้ว!</color></size>",
  str_n7_paper_5_5_title = "<size=35><color=#353330>กิลด์สิงโตน้ำเงินอาจพบจุดจบ\nครอบครัวโซลัสสาบสูญ</color></size>",
  str_n7_paper_1_1_content = "<size=35><color=#353330>　　ด้วยการสนับสนุนทางการเงินของคุณไรน์จากกิลด์สิงโตน้ำเงิน ตอนนี้ไนท์เทียมจำนวนมหาศาลกำลังรอผู้ชนะทัวร์นาเมนต์อารีน่าใต้ดินอยู่ เพื่อตอบรับคำขอบคุณที่ท่วมท้นจากผู้จัดงาน ไรน์อ้างว่าการช่วยเหลือครั้งนี้เป็นแค่รายรับต่อวันของสิงโตน้ำเงิน ยักษ์ใหญ่ด้านการค้าในตำนานแห่งอัมบราตัน\n　　อารีน่าใต้ดินไม่ใช่ได้ชื่อนี้เพราะสถานที่ตั้งอยู่ใต้ดินของเมือง แต่เพราะกฎของมัน ซึ่งก็คือการไม่มีกฎเกณฑ์ใดเลยนั่นเอง ผู้ชนะจะได้นอนบนกองทองอย่างแน่นอน ส่วนผู้แพ้ก็อาจได้นอนหลับยาวชั่วนิรันดร์ นักสู้ที่ไม่ค่อยกล้าหาญจำนวนมากในเมืองนี้เคยลังเลใจ แต่เนื่องจากปีนี้มีกองรางวัลมหาศาล นักสู้ทุกคนจึงสวมวิญญาณนักแข่งขันขึ้นมาในชั่วข้ามคืน สำนักงานลงทะเบียนมีผู้ท้าทายมาติดต่ออย่างคับคั่งทุกวัน บ้างก็สู้กันข้างถนนเสียเลยเพื่อเป็นการอุ่นเครื่องก่อนถึงการแข่งขัน\n　　ในส่วนของกิจกรรมครั้งยิ่งใหญ่นี้ ผู้จัดจึงได้ขอขอบคุณไรน์อีกครั้งสำหรับความช่วยเหลือ ในขณะที่ไรน์ผู้ทรงเกียรติบอกว่า \"ไม่ต้องขอบคุณผมหรอก ผมควรขอบคุณคุณมากกว่าสำหรับความหลงใหลที่คุณได้แสดงออกต่ออารีน่าใต้ดิน ผมยินดีที่ได้เห็นความตื่นเต้นที่เกิดขึ้นจากสนามประลองในช่วงเวลาที่เราต้องพบกับความเศร้าซึม ไม่สำคัญหรอกว่าคุณจะได้รางวัลหรือเปล่า ผมหวังว่าทุกคนในอัมบราตันจะสามารถลืมปัญหาของตัวเองและสนุกกับความตื่นเต้นของสนามประลองนี้ได้อย่างถ้วนทั่ว\"\n　　ใคร ๆ ก็อดตั้งข้อสังเกตไม่ได้ว่าไรน์นั้นช่างเสียสละและรักอารีน่าใต้ดินมากเหลือเกิน ขอให้กิลด์สิงโตน้ำเงินจงเจริญและสนับสนุนกิจกรรมนี้อีกในปีต่อ ๆ ไป!\n</color></size>",
  str_n7_paper_1_2_content = "<size=35><color=#353330>　　ไม่นานมานี้มีผู้พบเห็นอีสต์วานเดินอยู่ในป่านอกเมืองอัมบราตัน แต่ละครั้งจะเปลี่ยนสถานที่ไปเรื่อย ๆ โชคดีที่นักข่าวของเราลับคมทักษะการติดตามมาจากในกองทัพ และได้รับตำแหน่งแชมเปี้ยนมาราธอนอพยพสนามรบประจำปี ในที่สุดเขาก็พบเจ้าแห่งเงาในหุบเขาทางตอนเหนือของอัมบราตัน กลายเป็นว่าอีสต์วานเป็นผู้ชายที่ลึกลับและมีเสน่ห์อย่างยิ่ง!\n　　นักข่าวของเราพยายามอย่างสุดตัวที่จะติดตามอีสต์วานเพื่อถามความเห็นเขาในประเด็นเรื่องการลงทุนของกิลด์สิงโตน้ำเงินในอารีน่าใต้ดิน เจ้าแห่งเงาตอบว่า \"ผมจะคอยดู\"\n　　อย่างที่เรารู้กันว่าอีสต์วานเอนเอียงไปทางฝ่ายที่ต้องการให้สั่งห้ามการแข่งขันประเภทนี้ ดังนั้นนักคาดการณ์หลายคนจึงเชื่อว่าการลงทุนจำนวนมากของกิลด์สิงโตน้ำเงินในอารีน่าใต้ดินจึงเป็นการท้าทายอำนาจของอีสต์วานโดยตรง จากข่าวในอดีตที่ชี้ว่าอีสต์วานตั้งใจจะชิงอำนาจควบคุมอารีน่าใต้ดิน แต่หลังจากได้ยินคำตอบของเขาแล้ว ตอนนี้นักลงทุนเชื่อกันว่าเจ้าแห่งเงามีเรื่องสำคัญกว่านั้นอยู่ในใจ ทำให้พวกเขาซื้อพันธบัตรจำนวนมากจากกิลด์สิงโตน้ำเงิน</color></size>",
  str_n7_paper_1_3_content = "<size=28><color=#353330>　　เมื่อสิบเจ็ดปีก่อน อีราเวลถูกทำลาย และมีเคเลสไทต์ซึ่งเป็นศัตรูตัวฉกาจของอิคลิพไซท์จำนวนน้อยมากที่เหลือรอดชีวิต เคเลสไทต์เหล่านี้มีพลังจิตที่ทรงพลังและสามารถส่งผลต่อจิตใจของผู้อื่นได้อีกด้วย บ้างก็ว่าเคเลสไทต์สามารถแปลงร่างออโรเรียนให้เป็นอิคลิพไซท์ได้ด้วยซ้ำ\n　　มีรายงานว่าเคเลสไทต์คนสุดท้ายได้มาถึงอัมบราตันแล้ว แรงจูงใจของเขายังไม่เป็นที่ล่วงรู้ ชาวอัมบราตันทั้งหมดต่างแนะนำให้คอยระวังความปลอดภัยส่วนบุคคลไว้ให้ดีอยู่เสมอ ถ้าคุณเห็นเคเลสไทต์ผู้นั้น โปรดอยู่ให้ห่าง เพื่อหลีกเลี่ยงการถูกครอบงำจิตใจหรือแปลงร่างเป็นอิคลิพไซท์</color></size>",
  str_n7_paper_1_4_content = "<size=28><color=#353330>　　ฤดูฝนกำลังมา คุณพบปัญหาผ้าไม่แห้งบ้างหรือเปล่า? นอกจากบริการตามกฎหมายจำนวนมากมายที่มีให้บริการแล้ว งานจิปาถะซึ่งเป็นร้านค้าที่รับประกันความพึงพอใจในทุกครั้ง ยังได้เปิดบริการตากแห้งลูมินาติกส์อีกด้วย! ไม่ว่าจะเป็นเสื้อ เสื้อกันหนาว เสื้อขนสัตว์ ผ้าพันคอไหมพรม หรือแม้แต่กระเป๋าหนังแบรนด์เนมใบใหม่ของคุณ ทาคิจะใช้ลูมินาติกส์ที่ร้อนระอุและดีต่อสุขภาพ เพื่อให้สิ่งของของคุณมีกลิ่นหอมพิเศษและแห้งได้ในเวลาอันรวดเร็ว ดมให้ชื่นไปทั้งหัวใจด้วยไอแดด สูดกลิ่นหอมอบอวลนี้และโอบกอดพลังแห่งฤดูร้อนชั่วนิรันดร์ได้เลย!\n　　บริการแก้ไขปัญหาหนี้สินฟรีเมื่อใช้บริการสำหรับเสื้อผ้าห้าสิบชิ้นต่อหนึ่งใบเสร็จ (แก๊งที่มีสมาชิกเกิน 100 คนอยู่ในสถานะลูกหนี้จะมีค่าบริการเพิ่มเติม)</color></size>",
  str_n7_paper_1_5_content = "<size=28><color=#353330>　　กิลด์มิลเลอร์ ซึ่งมีร้านค้าอัมบราตันอายุนับศตวรรษ มีชื่อเสียงด้านบริการการจำหน่ายต่อด้วยความเป็นมืออาชีพระดับคุณภาพ เนื่องจากปัญหาสถานการณ์ความปลอดภัยสาธารณะที่เกิดความวุ่นวายมากขึ้นอย่างต่อเนื่องในอัมบราตันเมื่อเร็ว ๆ นี้ อาชญากรส่วนใหญ่ได้ใช้วิธีการที่แปลกใหม่และแหกกฎเพื่อขายสินค้าที่ขโมยมา บ้างก็เร่ขายของที่ขโมยมาตามถนนหนทาง เปิดสงครามราคาที่ส่งผลให้ยอดขายของกิลด์มิลเลอร์ลดลงอย่างมาก เพื่อช่วยไม่ให้กิลด์ต้องเสียหาย มิลเลอร์ที่สาม ซึ่งเป็นหัวหน้ากิลด์จึงหันไปหาการพนันอย่างรวดเร็ว และหลังจากสร้างหนี้การพนันขึ้นมามหาศาล เขาก็ดูเหมือนจะหลบหนีไปและไม่มีใครรู้ว่าเขาอยู่ที่ไหน\n　　ขณะนี้สหพันธ์การพนันได้ให้สิทธิ์กับหนังสือพิมพ์ของเราในการนำสินค้าผิดกฎหมายของกิลด์มิลเลอร์มาจำหน่ายต่อในราคาพิเศษ แหล่งข่าวที่เชื่อถือได้กล่าวว่า แก๊งขนาดใหญ่ในอัมบราตันจะร่วมกันปฏิบัติการเร็ว ๆ นี้เพื่อเสริมความปลอดภัยสาธารณะในอัมบราตัน และจับกุมผู้ค้าสินค้าผิดกฎหมาย โดยหวังว่าปฏิบัติการนี้จะแก้ปัญหาความล้มเหลวของธุรกิจหลักของกิลด์มิลเลอร์ได้</color></size>",
  str_n7_paper_2_1_content = "<size=35><color=#353330>　　การแข่งขันอารีน่าใต้ดินกำลังจะเริ่มต้น และความป่าเถื่อนของผู้แข่งขันก็เริ่มล้นทะลักออกมานอกสังเวียนสู่ถนนหนทางทั่วไป เนื่องจากมีการพบผู้ท้าทายที่มีชื่อเสียงหลายคนตามตรอกซอกซอยในเมือง สิ้นสภาพเพราะผู้เข้าแข่งขันด้วยกันเอง การดวลสุดโหดในช่วงสองสามวันที่ผ่านมาได้ดึงเอาสกิลพิเศษของนักสู้หลายคนออกมา รวมถึงนักสู้ชั้นนำที่น่าตื่นเต้นและชื่อเสียงโด่งดังอย่างเบ็กเกอร์ ที่เลื่อนชั้นเข้าสู่รอบต่อไปได้สำเร็จ น้อยคนที่จะลืมวินาทีที่เขาทำลายมือจับประตูโลหะของสนามประลองได้ แน่นอนว่าเบ็กเกอร์เป็นมากกว่านักแสดงที่มีเสน่ห์ ตั้งแต่แข่งขันมา เขายังทำลายคู่แข่งทั้งหมดไปแล้วอีกด้วย ใช่แล้ว ทำลาย ไม่ใช่แค่เอาชนะ ตอนนี้ผู้ท้าทายทั้งหมดที่ดวงตกจนต้องเผชิญหน้ากับเบ็กเกอร์ไปนอนรวมกันอยู่ในห้องเดียวที่โรงพยาบาลอัมบราตันเจเนอรัล และจะไม่สามารถแข่งขันในปีนี้ได้อีกต่อไป\n　　ดูจากกำหนดการแข่งขันแล้ว คู่แข่งคนต่อไปของเบ็กเกอร์จัดว่าน่าเป็นห่วง ผู้มาใหม่คนนี้ลือกันว่าเป็นเคเลสไทต์คนเดียวที่มีชีวิตรอด แม้ว่าเราทุกคนจะอยากเห็นการต่อสู้อันน่าทึ่ง แต่เราก็หวังเช่นกันว่าร่างกายที่เปราะบางนั่นจะสามารถทนต่อกำปั้นเหล็กกล้าของเบ็กเกอร์ได้ด้วยเช่นกัน!\n　　แน่นอนว่าความแตกต่างมหาศาลด้านความแข็งแกร่งนี้ไม่ได้หมายความว่าผลลัพธ์ของการต่อสู้ครั้งนี้จะสรุปได้ล่วงหน้า! การวิจัยระบุว่ากิจวัตรในชีวิตแบบดั้งเดิมนั้นเป็นการจำกัดพัฒนาการของร่างกายอย่างมาก โดยเฉพาะในเรื่องของอาหาร ดังนั้นเราจึงขอแนะนำให้คุณรู้จักโปรตีนผงพาวเวอร์พันช์ พัฒนาโดยกิลด์สิงโตน้ำเงิน! ดื่มเป็นประจำทุกวันเพื่อพิชิตเป้าหมายใหม่ด้านความแข็งแรงของร่างกาย! ผู้ท้าทายดาวเด่นอย่างเบ็กเกอร์คือนักรบคนแรกที่ลองใช้ผลิตภัณฑ์นี้ และประสิทธิภาพก็ชัดแจ้งกับสายตาทุกคนที่ติดตามการแข่งขัน ติดต่อเราโดยตรงเพื่อซื้อโปรตีนผงพาวเวอร์พันช์วันนี้!\n</color></size>",
  str_n7_paper_2_2_content = "<size=35><color=#353330>　　สังคมชนชั้นสูงแห่งอัมบราตันและบุคคลที่มีชื่อเสียงจากทุกแวดวงต่างรอคอยคำเชิญให้เข้าร่วมเป็นส่วนหนึ่งของซาลอนและงานเลี้ยงนี้ด้วยความกระตือรือร้น ซาลอนไฮโซนี้มีอยู่ในอัมบราตันมานานหลายปีแล้วไม่ว่าจะในยามดีหรือยามร้าย นับตั้งแต่ก่อตั้งขึ้นมา มันได้มอบความสุขให้กับชนชั้นสูงและผู้มีชื่อเสียงมากหน้าหลายตา โดยมีเป้าหมายเพื่อนำทางอัมบราตันให้ก้าวไปสู่อนาคตที่ดีและเจริญรุ่งเรืองยิ่งขึ้น โดยอาศัยการแลกเปลี่ยนความคิดระหว่างคนจากหลายสาขาอาชีพ\n　　ผู้ดูแลจะจัดแสดงผลงานและงานศิลปะใหม่ ๆ ในงานที่กำลังจะจัดขึ้น ซึ่งรวมถึงรากเหง้าแห่งภูผา ลมหายใจมัจฉา รอยอุ้งเท้า และปัญญาว่างเปล่า ผู้มีชื่อเสียงในอัมบราตันจากทุกสาขาอาชีพได้รับการเชิญชวนให้พูดคุยเรื่องศิลปะร่วมกัน และผู้จัดก็ตื่นเต้นที่จะได้รับฟังเสียงประเมินของบุคคลทั้งหลายเหล่านี้\n　　เราหวังว่าทีมผู้จัดและผู้เข้าร่วมงานจัดแสดงจะมีค่ำคืนแห่งผลิตภาพ และขอบคุณผู้จัดที่ให้การสนับสนุนหนังสือพิมพ์ของเราอย่างมากมาย</color></size>",
  str_n7_paper_2_3_content = "<size=28><color=#353330>　　แมวฉันหาย... คำพูดใดก็ไม่สามารถอธิบายความสำคัญของมันที่มีต่อฉันได้! ได้โปรดช่วยฉันได้ไหมคะ? ถ้ามันกลับมาอย่างปลอดภัย ฉันจะขอบคุณอย่างมาก และจะตอบแทนด้วยกาแฟห้าสิบแก้ว!\n　　รายละเอียดแมวของฉัน: เป็นแมวเครื่องกลตัวเล็ก เหมือนจริงมาก แต่มองเห็นเลยว่าขาหน้าซ้ายตรงส่วนที่เกิดความเสียหายจะมีสายไฟอยู่ข้างใน มันมีริบบิ้นสีแดงผูกอยู่ที่คอและป้ายชื่อทองเหลืองห้อยอยู่ด้วย\n　　นอกจากนี้ดวงตาของมันยังมีหลากสีและงดงามมาก!\n　　ถ้าคุณมีข้อมูลใดก็ตาม โปรดติดต่อคอนนอลลี เจ้าของฮอลิเดย์คาเฟ่ ขอบคุณมากนะคะ!</color></size>",
  str_n7_paper_2_4_content = "<size=28><color=#353330>Courier Union ผู้ให้บริการระดับมืออาชีพที่มีชื่อเสียงระดับโลก เชื่อมั่นในการให้บริการระดับโลกแก่คนที่รักความสงบทั่ว Astra และหลังจากเตรียมการมาหลายเดือน Courier Union ก็พร้อมที่จะเปิดตัวบริการตกแต่งใหม่แล้ว! ไม่ว่าคุณจะอาศัยอยู่ในห้องเดี่ยวหรือคฤหาสน์ ทีมตกแต่งของ Courier Union สามารถให้บริการครบวงจรตั้งแต่การออกแบบและการจัดซื้อ ไปจนถึงการก่อสร้างและการประเมิน เราสัญญาว่าหากบริการไม่ได้ผลตามที่ต้องการ ตกแต่งใหม่ไม่มีค่าใช้จ่าย!\nหากคุณสั่งบริการตกแต่งผ่านหนังสือพิมพ์ของเรา คุณสามารถประหยัดเพิ่มอีก 50 Nightium นอกเหนือจากส่วนลด 20% ของคุณ! กิจกรรมนี้จำกัดเฉพาะเดือนนี้เท่านั้น ดังนั้นอย่าลืมสั่งซื้อโดยเร็วที่สุด! โปรดติดต่อตัวแทน Umbraton Eho สำหรับรายละเอียดเพิ่มเติม!</color></size>",
  str_n7_paper_2_5_content = "<size=28><color=#353330>ร้านค้าหลายร้านของกิลด์หลินได้ปิดตัวลงโดยไม่ทราบกำหนดการเปิดอีกครั้ง\n　　เมื่อเร็ว ๆ นี้เราได้ทำการสืบในพื้นที่เพื่อหาข้อมูลเกี่ยวกับข่าวลือเรื่องการปิดตัวร้านค้าจำนวนมากที่เป็นของกิลด์หลิน ตอนนี้เราสามารถรายงานได้แล้วว่าร้านเหล่านั้นได้ปิดตัวลงแล้วจริง ๆ การปิดร้านที่เกิดขึ้นนี้ไม่ได้มีการประกาศล่วงหน้า ทำให้ลูกค้าจำนวนมากได้รับความเสียหาย ผู้ที่เชี่ยวชาญในด้านนี้สงสัยว่าตระกูลหลินอาจกำลังวางแผนการสมคบคิด แต่ไม่มีผู้ใดทราบว่าร้านค้าเหล่านี้จะเปิดอีกครั้งเมื่อไร</color></size>",
  str_n7_paper_3_1_content = "<size=35><color=#353330>　　\"เมื่อเคเลสไทต์อยู่ในทีมนั่น... มันก็เหมือนมีคนน้อยลงหนึ่งคน แล้วก็มีไก่อ่อนเพิ่มมาอีกตัวหนึ่งมากกว่า\" เบ็กเกอร์ตะโกนออกมาก่อนการแข่งขัน\n　　อย่างไรก็ดี คนเราไม่มีทางแน่ใจได้เมื่ออยู่ในสนามรบ ภายใต้การสั่งการของเคเลสไทต์ ทั้งทีมเคลื่อนที่ราวกับสายลม ร่วมมือกันอย่างสมบูรณ์แบบ และโจมตีอย่างโหดร้าย ถ้าเบ็กเกอร์ไม่ได้ทำให้เกมหยุดลงเพราะบังเอิญซัดผู้พิพากษาจนสลบในระหว่างการต่อสู้ เขาก็คงร่วงในการโจมตีรอบแรก\n　　หลังกลับเข้าสู่การแข่งขัน เบ็กเกอร์หลบได้ทันก่อนถึงตาเคเลสไทต์โจมตี แต่อยู่ดี ๆ เขาก็ร้องออกมาด้วยความเจ็บปวดและล้มลงกับพื้น น้ำลายฟูมปาก จากนั้นเขาก็เริ่มสั่นเทิ้มไปทั้งตัวและไม่นานก็ถูกหามออกไปนอกสนามรบ แพทย์สนามกล่าวว่า ดูเหมือนว่าสปอนเซอร์จะให้เบ็กเกอร์กินโปรตีนผงพาวเวอร์พันช์ในระหว่างการแข่งขัน นั่นทำให้เกิดตะคริวที่หน้าท้องและทำให้เกิดอาการกล้ามเนื้อหน้าท้องกระตุกเนื่องจากความเครียด ทำให้เขาต้องยอมฝืนกล้ำกลืนในความพ่ายแพ้ บ้างก็บอกอีกด้วยว่าเคเลสไทต์เห็นแล้วว่าเบ็กเกอร์มีปัญหาในการต่อสู้ และใช้กลลวงซ่อนเร้นเพื่อทำให้เบ็กเกอร์เป็นตะคริว ไม่ว่าความจริงเรื่องนี้จะเป็นอย่างไร เหตุฉุกเฉินครั้งก็ทำให้เกิดความหวาดวิตกในหมู่ผู้เข้าแข่งขันหลายคนที่ใช้ผลิตภัณฑ์ชนิดเดียวกัน\n　　นักข่าวของเราบอกว่าความเงียบเข้าครอบงำสนามประลองหลังจากที่เคเลสไทต์ผู้นั้นได้รับชัยชนะโดยไม่คาดคิด บุคคลเดียวที่เริ่มหัวเราะอย่างหนักพอ ๆ กับที่เบ็กเกอร์หัวเราะก่อนการต่อสู้ก็คือมิลเลอร์ที่สาม กลายเป็นว่าเขาจนตรอกและได้ทุ่มเดิมพันข้างของเคเลสไทต์ด้วยทุกสิ่งที่มี อัตราต่อรองก่อนเริ่มต้นการแข่งขันทำให้เขาได้รับรางวัลมหาศาล และจากนั้นเขาก็ประกาศก้อง \"กิลด์มิลเลอร์พร้อมแล้วที่จะนำสินค้าทั้งหมดที่ขโมยมากลับออกมาขาย!\"\n</color></size>",
  str_n7_paper_3_2_content = "<size=35><color=#353330>　　นักข่าว: สวัสดีคุณเชโอล เมื่อเร็ว ๆ นี้กิลด์เหนือเมฆได้เริ่มแจกถุงของขวัญฟรี และชาวอัมบราตันทั้งเมืองก็พูดถึงเรื่องนี้กันหนาหูราวกับมีสมบัติฟรีตกลงมาจากฟ้า คุณช่วยเล่าแนวคิดเบื้องหลังการทำธุรกิจแบบนี้ให้เราฟังหน่อยได้ไหม?\n　　เชโอล: ได้สิ ก่อนอื่นเลย ขอขอบคุณที่สนับสนุนกิลด์เหนือเมฆ ความคิดเบื้องหลังของเรื่องนี้คือเพื่อแสดงความขอบคุณของเรา นี่คือเหตุผลที่ทางกิลด์ตัดสินใจมอบถุงของขวัญฟรีให้กับทุกคน\n　　นักข่าว: นักลงทุนหลายคนเชื่อว่าการกระทำนี้ของกิลด์เหนือเมฆจะทำให้สูญเสียรายได้ แต่อย่างไรก็ดี ผลลัพธ์ที่ได้กลับทำให้พวกเขาถึงกับพูดไม่ออก... ที่จริงแล้วรายได้ของกิลด์เหนือเมฆกลับเพิ่มขึ้น! คุณบอกเราได้ไหมว่าเป็นเพราะอะไร?\n　　เชโอล: เราได้เสริมภาพลักษณ์ของกิลด์เหนือเมฆในสายตาประชาชนให้แข็งแกร่ง ผลลัพธ์ก็คือ เราจะมีการอัปเกรดถุงของขวัญฟรีขึ้นอีก โดยทำให้เป็นถุงของขวัญฟรีใหญ่ยักษ์! ชาวเมืองอัมบราตันทุกคนจะได้รับคนละหนึ่งใบโดยไม่มีข้อผูกมัด!\n　　บทสรุป: กิลด์เหนือเมฆจงเจริญ! แม้ว่าพวกเขาจะแจกถุงของขวัญฟรี หลายคนก็ยังเกิดแรงบันดาลใจที่จะใช้จ่ายเพิ่มเติมอีกหลังจากที่เปิดถุงของขวัญของตัวเองแล้ว และผู้คนมากมายก็หลั่งไหลกันมาที่กิลด์เหนือเมฆเพื่อซื้อผลิตภัณฑ์ของพวกเขาเพิ่มเติม ตอนนี้ก็ได้เวลาที่นักข่าวคนนี้จะไปรับถุงของขวัญฟรีแล้วครับ!</color></size>",
  str_n7_paper_3_3_content = "<size=28><color=#353330>　　เมื่อวานนี้จู่ ๆ รถบรรทุกหลายคันก็ถูกโจมตีโดยกลุ่มอิคลิพไซท์กลายพันธุ์ อิคลิพไซท์เหล่านี้ซ่อนตัวอยู่ในเงามืด มีรูปร่างแปลกประหลาด มีพลังไม่จำกัด และอาจเป็นผลมาจากการทดลองของนักวิทยาศาสตร์บ้าคลั่งจากลูโมโพลิสก็ได้ อัมบราตันที่เรียบง่ายของเราตอนนี้เจอภัยจากสองทาง ทั้งลูโมโพลิสและอิคลิพไซท์ที่ถูกเสริมพลังให้แข็งแกร่งขึ้น!\n　　ในระหว่างการโจมตี มีคนฉลาดคิดโรยผงกำจัดอิคลิพไซท์ของเซนต์จอห์นเข้าใส่พวกอิคลิพไซท์ อิคลิพไซท์พวกนั้นพากันปิดหน้าปิดตาทันทีและกรีดร้องพร้อมกับวิ่งหนีไป ทุกคนในที่นั้นรอดชีวิต\n　　ผงกำจัดอิคลิพไซท์ของเซนต์จอห์นผลิตขึ้นจากกระบวนการที่ซับซ้อนแปดสิบแปดขั้นตอน และเป็นยาที่จำเป็นสำหรับทุกคน ทั้งสำหรับใช้ที่บ้านและพกพาติดตัว เพื่อต่อสู้กับสิ่งชั่วร้าย</color></size>",
  str_n7_paper_3_4_content = "<size=28><color=#353330>　　รายงานภายในล่าสุดกล่าวว่าไรน์ หัวหน้ากิลด์สิงโตน้ำเงิน ผู้เป็นหนึ่งในบุคคลที่ทรงอิทธิพลที่สุดของเมืองในช่วงหลายปีที่ผ่านมา ดูเหมือนจะมีการติดต่อกับอีสต์วานเป็นการส่วนตัวแบบต่อเนื่อง โดยหวังว่าทั้งสองฝ่ายจะอยู่ร่วมกันได้อย่างสงบสุขในอนาคต อีสต์วานเองก็ดูจะตอบรับด้วยไมตรีเช่นกัน\n　　แม้การดิ้นรนเพื่อครอบครองอำนาจระหว่างกิลด์สิงโตน้ำเงินและสำนักงานใหญ่กิลด์ซึ่งมีอีสต์วานเป็นหัวหน้าจะเป็นการส่งเสริมความเจริญมั่งคั่งและการพัฒนาในอัมบราตัน แต่ก็ทำให้เกิดปัญหาทางสังคมหลายประการโดยถ้วนทั่วเช่นกัน นักวิจารณ์บางคนเชื่อว่านี่คือก้าวสำคัญในการสร้างสันติภาพที่แท้จริงในอัมบราตัน เป็นสัญลักษณ์ของการปรองดองระหว่างกองกำลังใหม่และเก่าในเมืองนี้\n　　คนบางส่วนเชื่อด้วยเช่นกันว่านี่เป็นเพียงอุบายของทั้งสองฝ่าย สิ่งที่เราเห็นกันอยู่นี้เป็นเพียงความสงบก่อนที่พายุกำลังจะเข้าเท่านั้น ยังมีการสมคบคิดครั้งใหญ่ยิ่งกว่ากำลังก่อตัวขึ้น</color></size>",
  str_n7_paper_3_5_content = "<size=28><color=#353330>ตามแหล่งข่าวที่เชื่อถือได้ เมื่อเร็ว ๆ นี้ตระกูล Solus ได้คัดเลือกกองทหารอย่างลับ ๆ เพื่อจัดตั้งทีมงานมืออาชีพที่มีทักษะในการปฏิบัติการลับ และยังคัดเลือก Mund ซึ่งเป็น Stealth King อีกด้วย มีข่าวลือมากมายว่าการหายตัวไปอย่างลึกลับของบุคคลสำคัญหลายคนจาก Umbraton และ Lumopolis มีความเชื่อมโยงกับ Mund อย่างแยกไม่ออก ปัจจุบันสมาชิกที่สงสัยว่ามีผลประโยชน์ทับซ้อนกับองค์กรชุมชนหายไปหลายคน\nทีมงานมืออาชีพที่รวบรวมโดยตระกูล Solus อาจทำให้คำสั่งปัจจุบันของ Umbraton สั่นคลอนในไม่ช้า</color></size>",
  str_n7_paper_4_1_content = "<size=35><color=#353330>　　เขื่อนแห่งรอยแผลถูกทำลาย ข่าวน่าตกใจนี้แพร่กระจายไปทั่วอัมบราตันและทำให้ในเมืองเกิดความสับสนวุ่นวายขึ้นอย่างมาก อย่างไรก็ดี เราสามารถรายงานได้อย่างมั่นใจว่าผู้ร้ายเบื้องหลังการทำลายเขื่อนนั้นไม่ใช่ใครอื่นนอกจากไรน์ หัวหน้ากิลด์สิงโตน้ำเงิน ซึ่งได้ถูกนำตัวมาดำเนินคดีโดยอีสต์วาน ผู้ปกป้องที่ซื่อสัตย์ของอัมบราตัน\n　　เหตุการณ์นี้ทำให้เกิดน้ำหลากไหลเชี่ยวที่มุ่งหน้าสู่อัมบราตัน อีสต์วานได้ยืนต้านกระแสน้ำอย่างมั่นคงอีกครั้งหนึ่ง เขาได้สั่งการให้ทหารรับจ้างระบายน้ำและผันน้ำออกจากพื้นที่เพื่อช่วยให้ชาวเมืองหนีออกจากพื้นที่อันตรายได้ นอกจากนี้อีสต์วานยังประสานกับกองกำลังต่าง ๆ ของตนเองให้ทำงานร่วมกับกิลด์เหนือเมฆเพื่อช่วยชีวิตผู้ที่ได้รับบาดเจ็บ จากนั้นเขาได้ส่งแก๊งของตัวเองไปจบชีวิตโซลัสและเหล่าสาวก ผู้ซึ่งวางแผนการที่จะใช้โอกาสนี้ทำลายอัมบราตัน ต้องขอบคุณภาวะผู้นำที่ชาญฉลาดของอีสต์วาน อัมบราตันรอดพ้นวิกฤตครั้งนี้มาได้โดยไม่เสียหายอะไรมากนัก เราขอขอบคุณอีกครั้งสำหรับการอุทิศตนแบบไม่เห็นแก่ตัวเพื่ออัมบราตัน\n　　ขอให้อีสต์วานปกป้องอัมบราตันต่อไปทั้งในเวลานี้และในภายภาคหน้าด้วยใจจริง\n</color></size>",
  str_n7_paper_4_2_content = "<size=35><color=#353330>　　ปกติก็ต้องเชียร์ม้ามืดกันอยู่แล้ว เคเลสไทต์ผู้นั้นชนะการต่อสู้ทั้งหมดมาหลายวันติดต่อกัน ตอนนี้สายตาทุกคู่จับจ้องอยู่ที่เคเลสไทต์คนสุดท้ายที่คืบหน้าไปในการแข่งขัน กลายเป็นผู้เล่นที่ได้รับความนิยมสูงสุดคนหนึ่งในสนามรบ กลุ่มผู้สนับสนุนที่เรียกตนเองโดยรวมว่า \"เลิฟเกเตอร์\" ได้เติบโตขึ้นมากแล้ว\n　　แต่ตอนนี้เราจะเน้นที่กิจกรรมที่เกิดขึ้นภายนอกสนามประลอง น่าเสียดายที่กลุ่มผู้สนับสนุนของเคเลสไทต์ได้ก่อความไม่สงบขึ้นตามถนนหนทาง มีส่วนในการปะทะต่อสู้บ่อยครั้งกับกลุ่มผู้สนับสนุนของผู้เล่นคนอื่น ๆ ในช่วงสองวันที่ผ่านมา เมื่อคืนนี้พวกเขาถึงกับก่อความรุนแรงขึ้นในกลุ่มคนที่เข้าชมการแข่งขัน ทำให้เกิดความวุ่นวายขึ้นในวงกว้าง ตามรายงานระบุว่า เคเลสไทต์ไม่ทราบถึงเรื่องที่เกิดขึ้นเหล่านี้ แต่ก็มองออกได้ไม่ยากว่าการถือกำเนิดขึ้นของม้ามืดเคเลสไทต์ได้ทำให้ความไม่ลงรอยกันระหว่างกลุ่มผู้สนับสนุนที่มีอยู่ก่อนหน้านี้เพิ่มความตึงเครียดมากยิ่งขึ้น ผู้สนับสนุนเคเลสไทต์ส่วนใหญ่คือกลุ่มคนรุ่นใหม่ที่ต้องการความเปลี่ยนแปลง ส่วนผู้สนับสนุนที่มีข้อพิพาทกันคือพวกหัวเก่าที่ต้องการให้แชมเปี้ยนผู้ครองสนามประลองคนเดิมได้กลับมา\n　　ความไม่ลงรอยกันระหว่างสองฝ่ายที่มีมาพักหนึ่งแล้ว ทำให้การถือกำเนิดขึ้นของม้ามืดเหมือนเป็นการเติมเชื้อเพลิงให้กองไฟ ส่งผลให้เกิดไฟนรกที่พร้อมระอุถึงขีดสุด ม้ามืดผู้นี้จะไปได้ไกลแค่ไหน เรามารอดูกัน</color></size>",
  str_n7_paper_4_3_content = "<size=28><color=#353330>　　ดินแดนที่ควบคุมโดยสเปียร์โรว์ผู้ดุดันได้รับรางวัลความปลอดภัยสาธารณะอีกครั้ง เมื่อนักข่าวของเราสัมภาษณ์เดย์นาและโรบินเพื่อสอบถามว่าสเปียร์โรว์ทำอย่างไรถึงจับตัวสมาชิกแก๊งข้างถนนต่าง ๆ ได้หลายสิบคนอย่างต่อเนื่องในแต่ละสัปดาห์ หัวหน้าผู้อ่อนวัยและถ่อมตนกล่าวว่า \"พวกโง่ตามข้างถนนพยายามทำร้ายโรบินกันอยู่ตลอด... นี่! แกตรงนั้นน่ะ! มองหน้าหาอะไรฮึ?!\"\n　　เราขอขอบคุณเดย์นาและโรบินที่มีส่วนร่วมในการรักษาความปลอดภัยให้กับชุมชนอย่างยอดเยี่ยม</color></size>",
  str_n7_paper_4_4_content = "<size=28><color=#353330>　　มีรายงานว่าไรน์ลักลอบจัดการประมูลผิดกฎหมายโดยใช้ซาลอนจัดแสดงงานศิลปะเป็นฉากบังหน้า นักข่าวของเราได้ยืนยันแล้วว่าผู้ได้รับผลประโยชน์ทั้งหมดที่เกี่ยวข้องถูกจับกุมแล้ว\n　　หนังสือพิมพ์ของเราขอประกาศไว้ในที่นี้ว่าเราไม่ทราบถึงการกระทำที่ผิดกฎหมายของกิลด์สิงโตน้ำเงิน รายงานทั้งหมดที่เกี่ยวข้องที่ตีพิมพ์ถึงซาลอนในช่วงที่ผ่านมานั้นมีความโปร่งใสและดำเนินการเพื่อวัตถุประสงค์ทางการค้าเท่านั้น ในอนาคตเนื้อหาทั้งหมดจะได้รับการตรวจสอบและยืนยันอย่างเคร่งครัดมากยิ่งขึ้น เพื่อหลีกเลี่ยงการแพร่กระจายของข้อมูลที่อาจส่งผลกระทบในแง่ลบต่อสังคมอัมบราตัน</color></size>",
  str_n7_paper_4_5_content = "<size=28><color=#353330>　　พบร่างอิคลิพไซท์เสริมพลังจำนวนมากในตรอกข้างคอร์นวอลล์คาเฟ่ ถนนครอสสตรีท บริกรคนหนึ่งที่คาเฟ่บอกเราว่าเธอได้ยินเสียงแปลก ๆ ตอนปิดร้านเมื่อคืนนี้ เธอมองเห็นจากหน้าต่างร้านว่ามีชายร่างบึกบึน สวมเครื่องแบบศาลยุติธรรมแห่งลูโม กำลังโยนร่างอิคลิพไซท์เข้าไปในตรอกทีละตัว\n　　ร่างเหล่านี้เริ่มเน่าเปื่อยแล้ว ทำให้เกิดกลิ่นเหม็นฉุนในพื้นที่โดยรอบ ขอให้ผู้ที่มีส่วนรับผิดชอบติดต่อสำนักงานเพื่อสุขอนามัยถนนอัมบราตันโดยเร็วที่สุดเพื่อชำระค่ากำจัดและค่าปรับที่เกี่ยวข้อง มิฉะนั้นอัมบราตันจะไม่มีหนทางอื่นนอกจากตั้งข้อหากับศาลยุติธรรมแห่งลูโมในการสร้างมลภาวะให้กับสิ่งแวดล้อม</color></size>",
  str_n7_paper_5_1_content = "<size=35><color=#353330>　　เราเพิ่งได้เห็นการแข่งขันที่ตื่นเต้นและดุเดือด ต้องขอบคุณม้ามืด หรือพูดให้ถูกก็คือ ต้องขอบคุณเคเลสไทต์ผู้กล้าแกร่ง! ขอบคุณที่ทำให้เราได้ชมการแข่งขันที่น่าทึ่งแบบนี้!\n　　เมื่อดูจากเกมก่อน ๆ การซื้อข้อมูลจากตลาดมืด และการแอบฟังเขาคุยกัน ผู้เข้าแข่งขันที่แข็งแกร่งจำนวนมากในการแข่งขันนี้ได้เรียนรู้กลยุทธ์ของเคเลสไทต์ผู้นี้แล้ว ดังนั้นเมื่อเผชิญหน้ากับการโจมตีที่เฉียบคมของทีมเคเลสไทต์ ผู้เข้าแข่งขันเหล่านี้จึงไม่สามารถใช้กลยุทธ์แบบดั้งเดิมที่ชัดเจนได้ โดยเลือกที่จะโจมตีแบบพุ่งเข้าชนแทน! หลังจากการโจมตีสุดเถื่อนที่สิ้นหวังในลักษณะนี้ ในที่สุดพวกเขาก็ต้องชดใช้ให้กับความหุนหันพลันแล่นของตัวเอง และคงต้องไปนอนคิดทบทวนการตัดสินใจของตัวเองที่โรงพยาบาลท้องถิ่น!\n　　ไม่ทำให้เลิฟเกเตอร์ผิดหวัง! ไม่ปล่อยให้คู่แข่งได้มีโอกาส! เคเลสไทต์จงเจริญ! เมื่อเผชิญกับกลยุทธ์แบบระบุเป้าหมายและแผนการที่แยบยลของคู่แข่ง จะมัวทักท้วงเรื่องกลลวงกลโกงของพวกเขากับกรรมการไม่ได้ และเคเลสไทต์ของเราได้แสดงให้เห็นถึงพรสวรรค์ด้านกลยุทธ์และภาวะความเป็นผู้นำที่สง่างาม ซึ่งได้รับตกทอดมากจากเหล่าผู้บัญชาการเคเลสไทต์ที่เคยอยู่ในลูโมโพลิส อิลลูมินา อีราเวล อัมบราตัน และนอร์ธแลนด์ ต้องฉวยโอกาสคว้าชัยชนะให้ได้! ประเพณีที่ยิ่งใหญ่ของเคเลสไทต์!\n　　เคเลสไทต์ของเราคือหนึ่งในล้านอย่างแท้จริง เขามีพลังอำนาจที่จะมองหาโอกาสโจมตีได้ชนิดที่คนทั่วไปไม่สามารถคว้าเอาไว้ได้ในการต่อสู้ทั้งชีวิต โอกาสที่พันปีจะวนผ่านมาสักครั้ง! ในเวลานี้ เคเลสไทต์ผู้นี้ไม่ได้ต่อสู้ตามลำพัง ผู้นำทางผู้ยิ่งใหญ่ ชัยชนะนี้เป็นของคุณ!\n　　ด้วยพลังที่โค่นล้มศัตรูได้ในการโจมตีที่เฉียบขาด ขอแค่สั่งมาคำเดียว! การโจมตีที่สร้างความเสียหายมหาศาล! ไม่เหลือแม้แต่โอกาสให้ศัตรูได้ตอบโต้! ทุกคนในกลุ่มผู้ชมเป็นพยาน! เคเลสไทต์ได้รับชัยชนะ ไม่ใช่แค่เพื่อตนเอง แต่เพื่อสหายชาวเคเลสไทต์ เพื่อทีม เพื่อสนามประลองใต้ดิน อีสต์วาน อัมบราตัน และเพื่อทุกคนทั่วโลกที่รักความตื่นเต้นของการต่อสู้! เคเลสไทต์จงเจริญ!\n　　*เราขอใช้โอกาสนี้ในการขอโทษผู้อ่านทั้งหมด เราไม่ได้เห็นการแข่งขันที่น่าตื่นเต้นแบบนี้มานานแล้ว เนื่องจากนักข่าวที่ได้เห็นการต่อสู้ครั้งสุดท้ายเป็นล้มไปแล้วเพราะความตื่นเต้นหลังจากเขียนรายงานสดข้างต้น บรรณาธิการบริหารจึงนำบทความนี้มาเขียนต่อไปด้วยตัวเอง\n　　ภายหลังจากที่เคเลสไทต์ได้รับชัยชนะ อีสต์วานได้มอบเข็มขัดให้กับผู้ชนะของเรา ซึ่งเป็นเครื่องหมายแทนความยิ่งใหญ่ที่สุดในสนามประลองใต้ดิน ทำให้เคเลสไทต์ได้รับพื้นที่ในโถงเกียรติยศ! เมื่อยกเข็มขัดขึ้นเหนือหัว ผู้ชมก็ปรบมือกันสนั่นยกใหญ่ นอกจากนี้เสียงเชียร์ยังดังกึกก้องไปทั้งสนามประลองเนิ่นนานราวกับชั่วนิรันดร์\n　　แชมเปี้ยนเคเลสไทต์ผู้แกร่งกล้า คุณจะมีพื้นที่ในหัวใจชาวอัมบราตันทุกคนตลอดไป!\n</color></size>",
  str_n7_paper_5_2_content = "<size=35><color=#353330>　　การประมูลใต้ดินถูกสั่งระงับเนื่องจากเกิดเหตุกบฏขึ้นเมื่อไม่นานนี้ ตอนนี้ได้ถือเป็นกิจกรรมที่ผิดกฎหมายเนื่องจากความเกี่ยวข้องกับไรน์ที่ไม่สามารถปฏิเสธได้ หลังจากได้ทราบข่าวร้ายนี้ ทั้งกลุ่มผู้ซื้อและผู้ขายจึงออกมาแสดงความคิดเห็นกันอย่างรุนแรง เนื่องจากพวกเขาจะไม่มีโอกาสได้ซื้อสินค้าประมูลหายากที่มี หรือหาประโยชน์จากการประมูลพวกนี้ได้อีก... ทำให้เกิดความกังวลเพิ่มขึ้นเป็นสองเท่า\n　　ท่ามกลางความเคราะห์ซ้ำกรรมซัดในสถานการณ์นี้ เบเธลได้เสนอว่าสำนักงานใหญ่ของกิลด์ต่าง ๆ ในอัมบราตันได้ชุบชีวิตการประมูลใต้ดินเหล่านี้กลับมาอย่างซื่อสัตย์ ใช่ ถูกต้องแล้ว การชุบชีวิตอย่างซื่อสัตย์! เธอสัญญาที่จะจัดการประมูลต่อไป จัดให้มีสถานที่แห่งใหม่ มีการโฆษณา และรักษาความปลอดภัย เพื่อชักนำให้ผู้ซื้อและผู้ขายในอัมบราตันที่สิ้นหวังได้เห็นแสงสว่างแห่งความหวังในที่สุด\n　　หลังจากนี้ ภายใต้การกำกับดูแลของสำนักงานใหญ่ประจำแต่ละกิลด์ การประมูลครั้งแรกจะจัดขึ้นที่จัตุรัสอัมบราตัน เมื่อทุกคนได้ยินเสียงค้อนกระทบดังกึกก้อง การประมูลนี้ก็ได้รับการยอมรับว่าเป็นกิจกรรมที่ถูกต้องตามกฎหมายอย่างเป็นทางการ นอกจากนี้เบเธลยังประกาศอีกด้วยว่า นับจากวันนี้ไป การประมูลบนดินจะเปิดกว้างกับทุกคน ทุกคนสามารถเข้าร่วมได้ ตราบใดที่มีการส่งใบสมัครให้กับสำนักงานใหญ่ประจำกิลด์และได้รับอนุญาตโดยไม่มีเงื่อนไขเพิ่มเติม! ผู้ที่มีส่วนเกี่ยวข้องในการประมูลดั้งเดิมถึงกับเช็ดน้ำตาด้วยความปลื้มใจที่ได้ยินข่าวนี้ พวกเขาปรบมือให้กับการตัดสินใจของเบเธลและประกาศว่าพวกเขาจะภูมิใจที่ได้เข้าร่วมการประมูลบนดิน\n　　การประมูลบนดินจงเจริญ! การค้าเสรีจงเจริญ!เบเธลจงเจริญ!</color></size>",
  str_n7_paper_5_3_content = "<size=28><color=#353330>　　ชื่อเสียงที่ไร้ขอบเขต! พลังการต่อสู้ ทักษะ และประสบการณ์ ล้วนเป็นคุณสมบัติที่สามารถเก็บเกี่ยวได้ แต่ไม่มีคุณสมบัติใดที่ขัดเกลาได้ยากไปกว่าความน่าเชื่อถืออีกแล้ว ในหน่วยทหารรับจ้างนี้ คุณสามารถพึ่งพาสหายของคุณได้อย่างสนิทใจ และหวังให้พวกเขาปฏิบัติต่อคุณด้วยจิตใจที่ดีได้</color></size>",
  str_n7_paper_5_4_content = "<size=28><color=#353330>　　ผู้ที่อาศัยในละแวกถนนครอสสตรีท พวกคุณเคยได้ยินเสียงหัวเราะประหลาดที่ดังก้องไปทั้งถนนในยามค่ำคืนไหม? แหล่งที่มาของเสียงหัวเราะนี้คือเงามืดที่เมื่อไม่นานมานี้มีผู้พบเห็นอยู่ที่ปลายถนน เงานี้เป็นอะไรที่ผิดธรรมชาติของออโรเรียนหรือไม่? หรือนี่คือรูปปรากฏของศีลธรรมที่เสื่อมถอยลงอย่างต่อเนื่องของเรา? บัดนี้เราจะไขปริศนานี้กัน เพื่อคุณโดยเฉพาะ... เงามืดที่หลอกหลอนอยู่ในอัมบราตันกลางดึกนี้ ที่จริงแล้วไม่ใช่ใครอื่นนอกจากมิลเลอร์ที่สาม\n　　เมื่อเร็ว ๆ นี้มิลเลอร์ที่สาม ผู้ซึ่งวางเดิมพันชัยชนะของเคเลสไทต์ไว้มหาศาล ได้สูญเสียเงินลงทุนไปเนื่องจากการล่มสลายของกิลด์สิงโตน้ำเงิน นอกจากนี้เขายังเสียตัวตนอย่างหนักจนถึงขั้นต้องหันมาเดินเหินตามที่ต่าง ๆ ในยามค่ำคืนราวกับภูตผีที่ไม่รู้เหน็ดเหนื่อย\n　　ตอนที่นักข่าวของเราต้อนเขาจนมุม และถามว่าตอนนี้เขารู้สึกยังไงเรื่องชัยชนะของเคเลสไทต์ เขาก็กรีดร้องและวิ่งหนีไปทันที นักข่าวของเราพบเพียงแค่รองเท้าของเขาหนึ่งข้างที่ปราศจากเชือกผูกอยู่บริเวณริมแม่น้ำ มิลเลอร์ที่สาม ผู้รับสืบทอดกิลด์อยู่นับศตวรรษ บัดนี้ได้หายตัวไป และสันนิษฐานว่าเสียชีวิตแล้ว\n　　ผู้ไล่ตามความฝันเหมือนกับเขาปรากฏขึ้นในอัมบราตันทุกวัน ตราบใดที่คุณสามารถปรับตัวให้เข้ากับกฎที่ไม่มีการบันทึกเอาไว้ของอัมบราตันได้ ที่นี่ก็จะเป็นสถานที่อันน่าอภิรมย์สำหรับคุณ แต่ถ้าหากทำไม่ได้แล้ว โชคชะตาอันไม่พึงประสงค์ก็จะรอคุณอยู่ เอ้อ อัมบราตันที่งดงามและลึกลับ ที่แห่งความหวัง ความปรารถนา และความฝันไร้ที่สิ้นสุด</color></size>",
  str_n7_paper_5_5_content = "<size=28><color=#353330>　　ครั้งหนึ่งการมีตำแหน่งในกิลด์สิงโตน้ำเงินเป็นเรื่องน่านับถือสำหรับชาวเมืองอัมบราตัน บัดนี้กิลด์สิงโตน้ำเงินได้กลายเป็นที่ดูถูกเหยียดหยามประจำเมืองไปแล้ว สมาชิกของกิลด์ต่างทิ้งเข็มกลัดที่ครั้งหนึ่งเคยภาคภูมิใจ และหันไปเข้าร่วมกับกิลด์อื่นแทนด้วยความหวังว่าจะมีชีวิตรอดในอัมบราตัน\n　　ตระกูลโซลัส ผู้ก่อความไม่สงบที่เกิดขึ้นเมื่อไม่นานมานี้ได้หายตัวไป และเป็นไปได้มากว่าจะหนีไปจากอัมบราตันเป็นที่เรียบร้อยแล้ว แหล่งต่าง ๆ ที่ไม่ประสงค์บอกนามพากันตั้งรางวัลในการนำส่งข้อมูลเกี่ยวกับตระกูลโซลัส หากคุณทราบที่อยู่หรือสถานะของบุคคลในตระกูลนี้ ไม่ว่าจะเป็นหรือตาย โปรดแจ้งมายังหนังสือพิมพ์ของเราทันที</color></size>",
